    public override void Render(DrawingContext context)
    {
        if (Kind == "Feather")
        {
            using (context.PushTransform(Matrix.CreateScale(Bounds.Width / 512, Bounds.Height / 512)))
                context.DrawGeometry(Foreground, null, Feather);
            return;
        }
        if (Kind is null || !Shapes.TryGetValue(Kind, out var shape)) return;
        using (context.PushTransform(Matrix.CreateScale(Bounds.Width / 20, Bounds.Height / 20)))
            if (Kind == "Sparkles") context.DrawGeometry(Foreground, null, shape);
            else context.DrawGeometry(null, new Pen(Foreground ?? Brushes.Black, 1.15, lineCap: PenLineCap.Round, lineJoin: PenLineJoin.Round), shape);
    }
